import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/roblox/screen-ui.html","title":"Screen UI","lang":"en-US","frontmatter":{},"git":{"updatedTime":1783917371000,"contributors":[{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/hifat"}],"changelog":[{"hash":"ed97d178848b9611e0cb11d64c28a664245c5a82","time":1783917371000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add roblox screen ui"}]},"filePathRelative":"roblox/screen-ui.md"}`),a={name:`screen-ui.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="screen-ui" tabindex="-1"><a class="header-anchor" href="#screen-ui"><span>Screen UI</span></a></h1><p><img src="https://youtu.be/_FUw-88-eHc" alt="YT"></p><p>วิดีโอนี้เป็นบทเรียนเบื้องต้นเกี่ยวกับ <strong>Screen GUI</strong> ใน <em>Roblox</em> โดยผู้สอน (Ethan) อธิบายถึงวิธีการสร้างและคุณสมบัติ (Properties) สำคัญต่างๆ ที่ใช้ในการปรับแต่งหน้าจอเมนูหรือส่วนติดต่อผู้ใช้งานภายในเกม:</p><ul><li><strong>การสร้าง Screen GUI (0:04):</strong> เริ่มต้นจากการเพิ่ม <em>Screen GUI</em> เข้าไปใน <em>Starter GUI</em> ซึ่งเป็นที่ที่เก็บข้อมูล UI ที่จะแสดงบนหน้าจอของผู้เล่น</li><li><strong>คุณสมบัติที่สำคัญ (0:22):</strong><ul><li><strong>Archivable (0:43):</strong> กำหนดว่า UI นี้สามารถคัดลอก (Clone) หรือบันทึกได้หรือไม่ หากปิดไว้ UI จะไม่แสดงผลและไม่ถูกคัดลอกไปยัง <em>Player GUI</em></li><li><strong>Display Order (2:23):</strong> ควบคุมลำดับชั้นการแสดงผลของ UI หลายตัว ยิ่งค่ามาก ยิ่งอยู่ด้านบน</li><li><strong>Enabled (3:32):</strong> สวิตช์เปิด-ปิดการแสดงผลของ UI</li><li><strong>Ignore GUI Inset (3:48):</strong> หากเปิดใช้งาน UI จะแสดงผลเต็มหน้าจอโดยไม่ถูกแถบบาร์ด้านบน (Top bar) ของ <em>Roblox</em> บดบัง เหมาะสำหรับการทำเมนูหลัก</li><li><strong>Reset on Spawn (5:10):</strong> กำหนดว่าเมื่อตัวละครตายและเกิดใหม่ UI จะหายไปหรือรีเซ็ตกลับไปเป็นค่าเริ่มต้นหรือไม่</li></ul></li></ul><p>วิดีโอนี้สรุปจบด้วยการแนะนำว่าในตอนถัดไป จะมีการพูดถึงเรื่องของ <strong>Frames</strong> และการปรับแต่งสี (Color properties) ต่อไป (6:40)</p>`,5)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};